mapper.select:
SELECT CASE fo.order_type WHEN 0 THEN '支出' WHEN 1 THEN '收入' END AS name, SUM(fo.amount) AS value
FROM finance_order fo
WHERE (fo.status IS NULL OR fo.status = 1)
AND fo.create_time >= #{startTime}
AND fo.create_time <= #{endTime}
AND fo.order_type = #{orderType}
GROUP BY fo.order_type
